sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
    // 6. ฟังก์ชัน callback เมื่อได้รับข้อมูลจากเซิร์ฟเวอร์
    function getBucket(response) {
        var answer = response.responseXML.documentElement.getAttribute('answer'); // 7. ดึงข้อมูลจาก XML response
        var result = JSON.parse(answer); // 8. แปลง JSON string เป็น Object
        g_form.setValue('limit', result.limit); // 9. กำหนดค่า limit ลงในฟอร์ม
    }
    // 2. สร้าง GlideAjax เพื่อเรียกใช้ ImsAjax Script Include
    var ga = new GlideAjax('ImsAjax');
    ga.addParam('sysparm_name', 'getCardBucket'); // 3. ระบุชื่อฟังก์ชันที่ต้องการเรียกใช้ (แก้ไขจากเดิมที่ไม่มีเครื่องหมายคำพูด)
    ga.addParam('sysparm_user', g_user.userID); // 4. ส่งค่า userID ของผู้ใช้ปัจจุบันไป

    ga.getXML(getBucket); // 5. ส่งคำขอและกำหนดฟังก์ชัน callback เมื่อได้คำตอบ



}
